import {shopItems,unlocked,buyItem,equipItem,applyLook,makePreview} from './shop.js';
export function createShop({state,inv,dinos,progress,save,pause,resume,sound,atCamp,message}){
 const $=id=>document.getElementById(id);let animalId='',itemId='blue',angle=0,preview,trying=true;
 const animal=()=>dinos.find(d=>d.id===animalId&&d.tame),item=()=>shopItems.find(i=>i.id===itemId);
 function draw(){const d=animal(),i=item();if(!d)return;const look={...state.looks[d.id],...(trying?{[i.kind]:i.id}:{})};try{preview??=makePreview($('shopCanvas'));preview.draw(d.index,look,angle);$('previewError').hidden=true;}catch{$('previewError').hidden=false;}}
 function render(){const d=animal(),i=item();$('shopBalance').textContent='💎 '+inv.gems+' diamants';$('shopEmpty').hidden=!!d;$('shopBody').hidden=!d;$('shopAnimals').replaceChildren();for(const a of dinos.filter(a=>a.tame)){const option=document.createElement('option');option.value=a.id;option.textContent=(a.nickname||a.s.name)+(a.refuge?' · au refuge':'')+(a.baby?' · bébé':'');$('shopAnimals').append(option);}$('shopAnimals').value=animalId;if(!d)return;
 $('shopGrid').replaceChildren();for(const product of shopItems){const button=document.createElement('button');button.className='shop-card'+(product.id===itemId?' selected':'');button.setAttribute('aria-pressed',String(product.id===itemId));button.innerHTML='<span class="shop-icon">'+product.icon+'</span><strong>'+product.name+'</strong><span>'+product.rarity+'</span><b>'+(state.owned.includes(product.id)?'Possédé ✓':!unlocked(product,progress())?'🔒 À débloquer':product.price+' 💎')+'</b>';button.onclick=()=>{itemId=product.id;trying=true;render();};$('shopGrid').append(button);}
 $('shopItemTitle').textContent=i.icon+' '+i.name;$('shopItemInfo').textContent=i.rarity+' · '+(i.kind==='skin'?'Couleur et motifs':'Accessoire')+' · '+(state.owned.includes(i.id)?'À toi pour toujours':i.price+' diamants');const owned=state.owned.includes(i.id),locked=!unlocked(i,progress());$('shopMessage').textContent=locked&&!owned?'🔒 '+i.hint:owned?'Tu peux l’utiliser gratuitement sur tous tes compagnons.':'Un achat pour tous tes compagnons. Aucun diamant dépensé pour essayer.';$('shopBuy').hidden=owned;$('shopBuy').disabled=locked||inv.gems<i.price;$('shopBuy').textContent=locked?'🔒 '+i.hint:inv.gems<i.price?'Il manque '+(i.price-inv.gems)+' 💎':'Acheter · '+i.price+' 💎';$('shopEquip').hidden=!owned;$('shopEquip').disabled=state.looks[d.id]?.[i.kind]===i.id;$('shopEquip').textContent=$('shopEquip').disabled?'Équipé ✓':'Porter sur '+(d.nickname||d.s.name);$('shopReset').textContent=i.kind==='skin'?'Retrouver sa couleur naturelle':'Retirer l’accessoire';draw();}
 $('shopAnimals').onchange=e=>{animalId=e.target.value;trying=true;render();};$('shopTurn').onclick=()=>{angle+=Math.PI/3;draw();};$('shopBuy').onclick=()=>{const d=animal(),i=item();if(!d)return;const result=buyItem(state,inv,i.id,progress());if(result==='bought'){equipItem(state,d,i.id,i.kind);applyLook(d.g,d.index,state.looks[d.id]);save();sound('craft');render();$('shopMessage').textContent='🎁 Acheté et équipé ! Tu peux le réutiliser sur tous tes amis.';}else render();};$('shopEquip').onclick=()=>{const d=animal(),i=item();if(equipItem(state,d,i.id,i.kind)){applyLook(d.g,d.index,state.looks[d.id]);save();render();}};$('shopReset').onclick=()=>{const d=animal();if(equipItem(state,d,null,item().kind)){trying=false;applyLook(d.g,d.index,state.looks[d.id]);save();render();$('shopMessage').textContent='Look retiré. Tes achats restent dans ta collection.';}};$('closeShop').onclick=resume;
 return {open(){if(!atCamp()){message('🛍️ La boutique est au camp. Appuie sur ⛺ Au camp pour y revenir.');return false;}pause();animalId=animal()?.id||dinos.find(d=>d.tame)?.id||'';render();if(!$('shopMenu').open)$('shopMenu').showModal();return true;}};
}
